PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?directorLabel WHERE {
  {
    <http://dbpedia.org/resource/God%27s_Comedy> dbo:director ?director .
  }
  UNION
  {
    <http://dbpedia.org/resource/God%27s_Comedy> dbp:director ?director .
  }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel WHERE {
  ?film rdfs:label ?filmLabel .
  FILTER(langMatches(lang(?filmLabel), "EN") && regex(?filmLabel, "God's Comedy", "i"))
  {
    ?film dbo:director ?director .
  }
  UNION
  {
    ?film dbp:director ?director .
  }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
} LIMIT 50

